#!/usr/bin/env python3
"""Optional: build port/fontdata_local.h from classic-Mac-style pixel fonts you supply (NOT part of the repo).
usage: gen/genfont_local.py FONTDIR   (FONTDIR holds ChicagoFLF.ttf and geneva_9.ttf from the tinkerdifferent.com
'classic Apple fonts' collection; licenses differ per font, so the generated file is git-ignored and for local use).
Produces 1-bit pixel strikes: family 3 = Chicago (QuickDraw font id 0) 12 px, family 4 = Geneva (font id 3) 9."""
import sys, os
from PIL import Image, ImageDraw, ImageFont
fd = sys.argv[1]
OUT = sys.argv[2] if len(sys.argv) > 2 else 'fontdata_local.h'
chars = [bytes([c]).decode('mac_roman') if c >= 32 and c != 127 else ' ' for c in range(256)]
SPECS = [  # fam, name, file, truetype px size, ascent, descent, label size, space advance override
    (3, 'Chicago', 'ChicagoFLF.ttf', 12, 10, 2, 12, None),
    (4, 'Geneva',  'geneva_9.ttf',   16, 7, 2, 9, 4),
]
blob = bytearray(); strikes = []
def make(fam, path, px, asc, desc, size, spc, bold):
    f = ImageFont.truetype(path, px); tbl = []
    for c in range(256):
        ch = chars[c]; adv = int(round(f.getlength(ch)))
        if ch == ' ' and spc is not None: adv = spc
        if c < 32 or c == 127: adv = 0
        im = Image.new('L', (px * 4, px * 3), 0); d = ImageDraw.Draw(im); d.fontmode = '1'
        d.text((px, px * 2), ch, font=f, fill=255, anchor='ls')
        if bold:
            from PIL import ImageChops; im2 = Image.new('L', im.size, 0); im2.paste(im, (1, 0)); im = ImageChops.lighter(im, im2)   # QuickDraw-style bold: smear 1 px
        bb = im.point(lambda v: 255 if v >= 128 else 0).getbbox()
        if bold and c >= 32: adv += 1
        if not bb or ch == ' ': tbl.append((adv, 0, 0, 0, 0, 0x40000000 + len(blob))); continue
        l, t, r, b = bb; w = r - l; h = b - t; rb = (w + 1) // 2; off = len(blob); px_ = im.load()
        for y in range(t, b):
            for xb in range(rb):
                v = 0
                for k in range(2):
                    x = l + xb * 2 + k
                    if x < r and px_[x, y] >= 128: v |= 15 << (4 if k == 0 else 0)
                blob.append(v)
        tbl.append((adv, l - px, w, h, px * 2 - t, 0x40000000 + off))   # top = rows above baseline
    return tbl
for fam, name, fn, px, asc, desc, size, spc in SPECS:
    p = os.path.join(fd, fn)
    if not os.path.exists(p): print('missing', p); continue
    for bold in (0, 1):
        strikes.append((fam, bold, size, asc, desc, make(fam, p, px, asc, desc, size, spc, bold)))
with open(os.path.join(os.path.dirname(__file__), '..', OUT), 'w') as o:
    o.write('/* generated by gen/genfont_local.py: ChicagoFLF (Robin Casady, public domain) and FontStruct Geneva 9 (Kelsey Higham, CC BY 3.0); see FONTS.md */\n')
    o.write('static const uint8_t local_blob[%d] = {' % max(1, len(blob)) + ','.join(str(x) for x in blob or [0]) + '};\n')
    for i, (fam, b, sz, asc, desc, tbl) in enumerate(strikes):
        o.write('static const FGlyph lg_%d[256] = {' % i + ','.join('{%d,%d,%d,%d,%d,%du}' % t for t in tbl) + '};\n')
    o.write('static const FStrike local_strikes[%d] = {' % len(strikes) + ','.join('{%d,%d,%d,%d,%d,lg_%d}' % (fam, b, sz, asc, desc, i) for i, (fam, b, sz, asc, desc, tbl) in enumerate(strikes)) + '};\n#define N_LSTRIKES %d\n' % len(strikes))
print('local strikes', len(strikes), 'blob', len(blob))
